    /// <summary>
    /// MPJ_21593 SVR document DCP 06/05/2022
    /// </summary>
    protected void initJournalHeader()
    {
        next initJournalHeader();

        vendInvoiceJour.METALMSupplierVolumetricRebateNumber = vendInvoiceInfoTable.METALMSupplierVolumetricRebateNumber;
    }

    /// <summary>
    /// Override of checkDiscardLine to ensure prepayment (advance application) lines
    /// are not discarded during VendInvoiceTrans creation.
    ///
    /// Background:
    /// - In the standard framework, lines of type PurchInvoiceLineType::AdvanceApplication
    ///   (prepayment application lines) are excluded when creating VendInvoiceTrans records.
    /// - This exclusion caused invoice journal lines not to be created for prepayment,
    ///   leading to runtime errors during posting (unable to initialize source document line).
    ///
    /// Fix:
    /// - By explicitly returning false when the line type is AdvanceApplication,
    ///   we prevent the discard and allow VendInvoiceTrans records to be created.
    /// - This ensures invoice journal lines are generated correctly and posting succeeds.
    ///
    /// Note:
    /// - Added to handle scenarios where prepayment invoices are applied to final invoices.
    /// - Review any customizations (e.g., Metcash-specific code) that may interact with
    ///   prepayment handling to avoid conflicts.
    /// </summary>
    protected boolean checkDiscardLine(Common _vendInvoiceInfoLine)
    {
        VendInvoiceInfoLine line = _vendInvoiceInfoLine;

        boolean ret = next checkDiscardLine(_vendInvoiceInfoLine);

        if (line.LineType == PurchInvoiceLineType::AdvanceApplication)
        {
            return false;
        }

        return ret;
    }
